const R = $json.valueRanges || [];
const vals = (R[0] || {}).values || [];
const START = 100;
const g = (row,i) => (row && row[i] != null) ? String(row[i]) : '';

// locate the Atomic Capital row by column B, never by remembered position
let target = -1, r = null;
for (let i = 0; i < vals.length; i++) {
  if (g(vals[i],1).trim().toLowerCase() === 'atomic capital') { if (target >= 0) throw new Error('two Atomic Capital rows in range'); target = START + i; r = vals[i]; }
}
if (target < 0) throw new Error('Atomic Capital row not found in Deal Tracker A100:T115');

const picked = g(r,5);
if (picked.toLowerCase().indexOf('eosnox') < 0) throw new Error('row ' + target + ' Picked/Interested no longer lists Eosnox - already corrected? value: ' + picked);
if (g(r,4).toLowerCase().indexOf('eosnox') < 0) throw new Error('row ' + target + ' All Deals Shared does not list EOSNOX - wrong row');

// remove only the EosNox entry, keep every other name exactly as written
const kept = picked.split(',').map(s => s.trim()).filter(s => s !== '' && s.toLowerCase().indexOf('eosnox') < 0);
if (kept.length !== 3) throw new Error('expected 3 remaining picked deals, got ' + kept.length + ': ' + kept.join(' / '));
const newPicked = kept.join(', ');

const PASSREASON = 'EosNox - taken to Atomic Capital’s investment committee and declined, 14 Sep 2026.';

const feedbackOld = g(r,15);
const ADD = 'EosNox, Apoorv Gautam, 14 Sep 2026 10:39 IST: "Thanks, we discussed it with our IC and they decided to go ahead with other opportunities on the table for now." EosNox was removed from Picked / Interested on 25 Sep 2026, having been left there for 11 days after the pass; the pass had not been recorded anywhere, in this sheet or in PIPELINE. It is now PIPELINE row 6588 (D07235). Bon-Cuisine, by contrast, is still live: shared 20 Jun 2026, three meetings (7 Jul, 14 Jul, and 31 Aug in person at IndiQube Penta Bengaluru) and financial diligence running founder-direct as of 25 Sep 2026; PIPELINE row 6587 (D07234).';
const newFeedback = feedbackOld.trim() ? (feedbackOld.trim() + ' | ' + ADD) : ADD;

const data = [
  { range: 'Deal Tracker!F' + target, values: [[newPicked]] },
  { range: 'Deal Tracker!O' + target, values: [[PASSREASON]] },
  { range: 'Deal Tracker!P' + target, values: [[newFeedback]] }
];
return [{ json: { body: { valueInputOption: 'RAW', data: data }, target_row: target, picked_before: picked, picked_after: newPicked, feedback_had_text: feedbackOld.trim().length > 0 } }];
